n de activos no financieros al valor razonable','67'=>'Gastos financieros','68'=>'Valuación y deterioro de activos y provisiones','69'=>'Costo de ventas','70'=>'Ventas','71'=>'Variación de la producción almacenada','72'=>'Producción de activo inmovilizado','73'=>'Descuentos, rebajas y bonificaciones obtenidos','74'=>'Descuentos, rebajas y bonificaciones concedidos','75'=>'Otros ingresos de gestión','76'=>'Ganancia por medición de activos no financieros al valor razonable','77'=>'Ingresos financieros','78'=>'Cargas cubiertas por provisiones','79'=>'Cargas imputables a cuentas de costos y gastos','80'=>'Margen comercial','81'=>'Producción del ejercicio','82'=>'Valor agregado','83'=>'Excedente bruto de explotación','84'=>'Resultado de explotación','85'=>'Resultado antes de participaciones e impuestos','88'=>'Impuesto a la renta','89'=>'Determinación del resultado del ejercicio'];
 $items=[];foreach($names as $code=>$name){$first=(int)substr((string)$code,0,1);$class=$first<=3?'asset':($first===4?'liability':($first===5?'equity':($first===6?'expense':($first===7?'income':'memo'))));$items[]=['code'=>(string)$code,'name'=>$name,'parent'=>null,'nature'=>in_array($class,['liability','equity','income'])?'credit':'debit','class'=>$class,'group'=>$class,'postable'=>false,'active'=>true];}
 $leaf=[['601','Mercaderías','60','expense','purchases'],['611','Mercaderías','61','expense','inventory_variation'],['395','Depreciación acumulada de propiedad, planta y equipo','39','asset','accumulated_depreciation'],['101','Caja','10','asset','cash'],['104','Cuentas corrientes en instituciones financieras','10','asset','bank'],['121','Facturas, boletas y otros comprobantes por cobrar','12','asset','receivable'],['201','Mercaderías','20','asset','inventory'],['401','Gobierno nacional','40','liability','tax'],['411','Remuneraciones por pagar','41','liability','payroll_payable'],['421','Facturas, boletas y otros comprobantes por pagar','42','liability','payable'],['501','Capital social','50','equity','capital'],['591','Utilidades no distribuidas','59','equity','retained'],['621','Remuneraciones','62','expense','payroll'],['639','Otros servicios prestados por terceros','63','expense','operating_expense'],['659','Otros gastos de gestión','65','expense','other_expense'],['684','Depreciación de propiedad, planta y equipo','68','expense','depreciation'],['691','Mercaderías','69','expense','cost_goods'],['701','Mercaderías','70','income','sales_goods'],['704','Prestación de servicios','70','income','sales_services'],['759','Otros ingresos de gestión','75','income','other_income']];
 foreach($leaf as $a)$items[]=['code'=>$a[0],'name'=>$a[1],'parent'=>$a[2],'nature'=>in_array($a[3],['liability','equity','income'])?'credit':'debit','class'=>$a[3],'group'=>$a[4],'postable'=>true,'active'=>true];
 foreach($items as &$i)if(in_array($i['code'],['395','611'],true))$i['nature']='credit';unset($i);
 foreach($items as &$i)if($i['code']==='79'){$i['class']='memo';$i['nature']='credit';$i['group']='analytic_transfer';}unset($i);
 // Separate IGV control subaccounts; classification is net liability, input credit has debit nature.
 foreach($items as &$i)if($i['code']==='401')$i['postable']=false;unset($i);
 $items[]=['code'=>'4011','name'=>'Impuesto general a las ventas','parent'=>'401','nature'=>'credit','class'=>'liability','group'=>'tax','postable'=>false,'active'=>true];
 foreach([['40111','IGV - Cuenta propia','credit'],['401111','IGV débito fiscal - control interno','credit'],['401112','IGV crédito fiscal - control interno','debit']] as $a)$items[]=['code'=>$a[0],'name'=>$a[1],'parent'=>$a[0]==='40111'?'4011':'40111','nature'=>$a[2],'class'=>'liability','group'=>'tax','postable'=>$a[0]!=='40111','active'=>true];
 return $items;
